CREATE    VIEW [synapse_ce].[vwIncident]
AS

	SELECT 
		inc.[incidentid]
		,inc.[statecode]
		,stStateCode.[LocalizedLabel] AS [statecode_description]
		,inc.[statuscode]
		,stStatusCode.[LocalizedLabel] AS [statuscode_description]
--		,inc.[apitil_escalationlevel]
--		,inc.[apitil_originatingsource]
--		,inc.[apitil_slastatus]
--		,inc.[apitil_urgency]
		,inc.[caseorigincode]
		,caseorigcode.[LocalizedLabel] AS [caseorigincode_description]
		,inc.[casetypecode]
		,casetypecode.[LocalizedLabel] As [casetypecode_description]
		,inc.[firstresponseslastatus]
		,inc.[incidentstagecode]
		,inc.[prioritycode]
		,inc.[resolvebyslastatus]
		,inc.[servicestage]
		,inc.[severitycode]
		,inc.[activitiescomplete]
		,inc.[adx_publishtoweb]
--		,inc.[apitil_converttoincident]
--		,inc.[apitil_converttoservicerequest]
--		,inc.[apitil_iscreatedthroughplugin]
--		,inc.[apitil_ispublic]
--		,inc.[apitil_isrespondedto]
--		,inc.[apitil_istickettemplateapplied]
--		,inc.[apitil_needsattention]
--		,inc.[blockedprofile]
--		,inc.[checkemail]
--		,inc.[customercontacted]
--		,inc.[decremententitlementterm]
--		,inc.[firstresponsesent]
--		,inc.[followuptaskcreated]
--		,inc.[isdecrementing]
--		,inc.[isescalated]
--		,inc.[merged]
--		,inc.[msdyn_copilotengaged]
--		,inc.[routecase]
--		,inc.[apitil_contact]
--		,inc.[apitil_contactname]
--		,inc.[apitil_team]
--		,inc.[apitil_teamname]
--		,inc.[createdby]
--		,inc.[createdbyname]
--		,inc.[createdonbehalfby]
--		,inc.[createdonbehalfbyname]
--		,inc.[firstresponsebykpiid]
--		,inc.[firstresponsebykpiidname]
		,inc.[masterid]
		,inc.[masteridname]
--		,inc.[modifiedby]
--		,inc.[modifiedbyname]
--		,inc.[modifiedonbehalfby]
--		,inc.[modifiedonbehalfbyname]
--		,inc.[msa_partnercontactid]
--		,inc.[msa_partnercontactidname]
--		,inc.[owningbusinessunit]
--		,inc.[owningbusinessunitname]
		,inc.[resolvebykpiid]
		,inc.[resolvebykpiidname]
		,inc.[subjectid]
		,inc.[subjectidname]
--		,inc.[transactioncurrencyid]
		,inc.[transactioncurrencyidname]
--		,inc.[ownerid]
		,inc.[owneridname]
		,inc.[customerid]
		,inc.[customeridname]
--		,inc.[adx_resolutiondate]
--		,inc.[apitil_contactname]
--		,inc.[apitil_contactyominame]
--		,inc.[apitil_dateandtimeofrecording]
--		,inc.[apitil_teamname]
--		,inc.[apitil_title]
		,inc.[caseage]
		,inc.[createdbyname]
--		,inc.[createdbyyominame]
		,inc.[createdon]
--		,inc.[createdonbehalfbyname]
--		,inc.[createdonbehalfbyyominame]
--		,inc.[customeridyominame]
		,inc.[deactivatedon]
		,inc.[description]
--		,inc.[emailaddress]
		,inc.[exchangerate]
		,inc.[firstresponsebykpiidname]
		,inc.[importsequencenumber]
		,inc.[modifiedbyname]
--		,inc.[modifiedbyyominame]
		,inc.[modifiedon]
--		,inc.[modifiedonbehalfbyname]
--		,inc.[modifiedonbehalfbyyominame]
--		,inc.[msa_partnercontactidname]
--		,inc.[msa_partnercontactidyominame]
		,inc.[nextsla]
--		,inc.[owneridyominame]
		,inc.[owningbusinessunitname]
--		,inc.[processid]
--		,inc.[resolvebykpiidname]
--		,inc.[slainvokedidname]
		,inc.[ticketnumber]
--		,inc.[timezoneruleversionnumber]
		,inc.[title]
		,inc.[apuk_responsedueon]
		,inc.[apuk_region]
		,inc.[apuk_casereopencount]
		,inc.[apuk_originatingdate]

	FROM synapse_ce.incident inc
		LEFT JOIN [synapse_ce].[StateMetadata] stStateCode
			ON inc.[statecode] = stStateCode.[State]
			AND stStateCode.[EntityName] = 'incident'
		LEFT JOIN [synapse_ce].[StatusMetadata] stStatusCode
			ON inc.[statuscode] = stStatusCode.[Status]
			AND stStatusCode.[EntityName] = 'incident'
		LEFT JOIN [synapse_ce].[GlobalOptionSetMetadata] caseorigcode			
			ON inc.[caseorigincode] = caseorigcode.[Option]
			AND caseorigcode.[OptionSetName] = 'caseorigincode'
			AND caseorigcode.[EntityName] = 'incident'
		LEFT JOIN [synapse_ce].[OptionSetMetadata] casetypecode			
			ON inc.[casetypecode] = casetypecode.[Option]
			AND casetypecode.[OptionSetName] = 'casetypecode'
			AND casetypecode.[EntityName] = 'incident'
